settings.custom_css:
.soharon-cart { font-family: 'Jost', sans-serif; color: #222; max-width: 1200px; margin: 0 auto; }

.soharon-cart__head,
.soharon-cart__row {
    grid-template-columns: 40px 90px 1fr 120px 170px; /* last col 120px -> 170px */
}

/* keep the whole price on one line */
.soharon-cart__row .col-price {
    white-space: nowrap;
    
}

.soharon-cart__row{
    padding: 0px!important;
}

/* Coupon bar */
.soharon-coupon-bar { background: #eee; border-radius: 6px; padding: 22px; text-align: center; margin-bottom: 30px;
max-width: 550px;
    margin: 0 auto 30px;
}
.soharon-coupon-bar p { margin: 0; font-weight: 300; color: #6D6E71; }
.soharon-coupon-bar .soharon-showcoupon { color: #222; font-weight: 400; text-decoration: none; }
.soharon-coupon-form { margin-top: 16px; display: flex; justify-content: center; align-items: center; gap: 8px; flex-wrap: wrap; }
.soharon-coupon-input { width: 320px; max-width: 100%; height: 48px; border: 1px solid #ccc; padding: 0 12px; font-family: 'Jost', sans-serif; font-weight: 300; font-size: 15px; }
.soharon-coupon-apply { height: 48px; padding: 0 24px; background: #222; color: #fff; border: none; font-family: 'Jost', sans-serif; font-weight: 300; text-transform: uppercase; cursor: pointer; }
.soharon-coupon-apply:hover { background: #474747; }
.soharon-coupon-msg { width: 100%; font-size: 14px; color: #6D6E71; }

/* Layout: items left, summary right */
.soharon-cart__layout { display: grid; grid-template-columns: 1fr 360px; gap: 60px; align-items: start; }

/* Items table */
.soharon-cart__head,
.soharon-cart__row {
    display: grid;
    grid-template-columns: 40px 90px 1fr 120px 120px;
    align-items: center;
    gap: 16px;
}
.soharon-cart__head { padding: 0 0 14px; border-bottom: 1px solid #e5e5e5; }
.soharon-cart__head span { font-weight: 300; letter-spacing: .04em; color: #222; }
.soharon-cart__head .col-qty,
.soharon-cart__row .col-qty { text-align: center; }
.soharon-cart__head .col-price,
.soharon-cart__row .col-price { text-align: right; }

.soharon-cart__row { padding: 26px 0; border-bottom: 1px solid #e5e5e5; }
.soharon-cart__row img { width: 100%; height: 155px; object-fit: cover; display: block; }
.soharon-cart__row .col-name a { color: #222; text-decoration: none; font-weight: 300; text-transform: uppercase; letter-spacing: .03em; }

.soharon-remove { background: none; border: none; font-size: 22px; line-height: 1; color: #777; cursor: pointer; padding: 0; }
.soharon-remove:hover { color: #000; }

/* Price */
.col-price del { color: #b0b0b0; font-weight: 300; margin-right: 8px; }
.col-price del .woocommerce-Price-amount { color: #b0b0b0; }
.col-price ins { text-decoration: none; font-weight: 400; color: #000; }

/* Qty stepper */
.soharon-qty { display: inline-flex; align-items: center; gap: 12px; }
.soharon-qty .sq-btn { background: none; border: none; font-size: 18px; line-height: 1; color: #6D6E71; cursor: pointer; padding: 0; width: 20px; }
.soharon-qty .sq-val { min-width: 16px; text-align: center; font-weight: 400; }

/* Summary */
.soharon-cart__summary { border-left: 0; }
.soharon-summary__title { font-weight: 300; letter-spacing: .04em; margin: 0 0 10px; font-size: 18px; }
.soharon-summary__row { display: flex; justify-content: space-between; align-items: center; padding: 22px 0; border-bottom: 1px solid #e5e5e5; font-weight: 300; color: #6D6E71; }
.soharon-summary__row span:last-child { color: #222; }
.soharon-summary__total span { font-weight: 400; color: #000; }
.soharon-freeship { text-align: center; font-weight: 300; font-size: 14px; color: #222; padding: 16px 0; margin: 0; }
.soharon-freeship--done { color: #1a7f37; }

.soharon-checkout-btn { display: block; width: 100%; background: #222; color: #fff; text-align: center; height: 56px; line-height: 56px; border-radius: 4px; text-decoration: none; font-weight: 300; letter-spacing: .08em; }
.soharon-checkout-btn:hover { background: #393939; color: #FFFFFF;}

.soharon-cart__empty { text-align: center; padding: 60px 0; font-weight: 300; }

/* Responsive */
@media (max-width: 900px) {
    .soharon-cart__layout { grid-template-columns: 1fr; gap: 40px; }
    
    .soharon-cart__row { grid-template-columns: 40px 70px 1fr; grid-auto-rows: auto; row-gap: 10px; }
    .soharon-cart__row .col-qty { grid-column: 2 / 4; text-align: left; }
    .soharon-cart__row .col-price { grid-column: 2 / 4; text-align: left; }
    .soharon-cart__row img { width: 70px; height: 70px; }
}

@media (max-width: 767px) {

    .soharon-cart,
    .soharon-cart * {
        box-sizing: border-box !important;
    }
    .soharon-cart {
        overflow-x: hidden !important;
        width: 100% !important;
    }
    .soharon-cart__layout {
        display: block !important;
        width: 100% !important;
    }

    .soharon-coupon-bar {
        width: 340px !important;
        max-width: 100% !important;
        border-radius: 9px !important;
        background-color: #e2e2e2 !important;
        margin: 0 auto 20px !important;
    }
    .soharon-coupon-bar p {
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 12px !important;
        color: #6d6e71 !important;
    }
    .soharon-coupon-bar .soharon-showcoupon {
        font-family: 'Jost', sans-serif !important;
        font-weight: 500 !important;
        font-size: 12px !important;
        color: #6d6e71 !important;
    }

    .soharon-cart__head {
        display: grid !important;
        grid-template-columns: 1fr 60px 60px !important;
        gap: 8px !important;
        padding: 0 0 14px !important;
    }
    .soharon-cart__head .col-remove,
    .soharon-cart__head .col-image {
        display: none !important;
    }
    .soharon-cart__head span {
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 11px !important;
        color: #6d6e71 !important;
        text-transform: uppercase !important;
    }
    .soharon-cart__head .col-qty { text-align: left !important; }
    .soharon-cart__head .col-price { text-align: right !important; }

    .soharon-cart__row {
        display: grid !important;
        grid-template-columns: 24px 55px 1fr 60px !important;
        grid-template-areas:
            "remove image name price"
            "remove image qty price" !important;
        row-gap: 6px !important;
        column-gap: 8px !important;
        padding: 16px 0 !important;
        border-bottom: 0.5px solid #6b6a6b !important;
        align-items: center !important;
        width: 100% !important;
        overflow: hidden !important;
    }

    .soharon-cart__row > .col-remove {
        grid-area: remove !important;
        min-width: 0 !important;
        align-self: start !important;
    }
    .soharon-remove { font-size: 16px !important; }

    .soharon-cart__row > .col-image {
        grid-area: image !important;
        min-width: 0 !important;
        align-self: start !important;
    }
    .soharon-cart__row img {
        width: 55px !important;
        height: 55px !important;
        object-fit: cover !important;
    }

    .soharon-cart__row > .col-name {
        grid-area: name !important;
        min-width: 0 !important;
        overflow: hidden !important;
        align-self: end !important;
    }
    .soharon-cart__row .col-name a {
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 13px !important;
        color: #222222 !important;
        white-space: nowrap !important;
        overflow: hidden !important;
        text-overflow: ellipsis !important;
        display: block !important;
    }

    .soharon-cart__row > .col-qty {
        grid-area: qty !important;
        min-width: 0 !important;
        align-self: start !important;
        text-align: left !important;
    }
    .soharon-qty .sq-btn { font-size: 14px !important; }
    .soharon-qty .sq-val {
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 14px !important;
        color: #222222 !important;
    }

    .soharon-cart__row > .col-price {
        grid-area: price !important;
        min-width: 0 !important;
        max-width: 60px !important;
        overflow: hidden !important;
        text-align: right !important;
        align-self: center !important;
    }
    .soharon-cart__row .col-price,
    .soharon-cart__row .col-price span,
    .soharon-cart__row .col-price bdi,
    .soharon-cart__row .col-price ins,
    .soharon-cart__row .col-price del,
    .soharon-cart__row .col-price .woocommerce-Price-amount,
    .soharon-cart__row .col-price .woocommerce-Price-currencySymbol {
        font-family: 'Jost', sans-serif !important;
        font-weight: 500 !important;
        font-size: 13px !important;
        line-height: 1.2 !important;
        color: #222222 !important;
        white-space: nowrap !important;
    }

    .soharon-cart__summary {
        width: 100% !important;
        margin-top: 30px !important;
    }
    .soharon-summary__title {
        font-family: 'Jost', sans-serif !important;
        font-weight: 700 !important;
        font-size: 16px !important;
        color: #222222 !important;
    }
    .soharon-summary__row {
        display: flex !important;
        justify-content: space-between !important;
        width: 100% !important;
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 12px !important;
        color: #000000 !important;
        border-bottom: 0.5px solid #e5e5e5 !important;
        padding: 10px 0 !important;
    }
    .soharon-summary__row span:last-child {
        font-family: 'Jost', sans-serif !important;
        font-weight: 500 !important;
        font-size: 14px !important;
        color: #222222 !important;
    }
    .soharon-summary__total span {
        font-family: 'Jost', sans-serif !important;
        font-weight: 500 !important;
        font-size: 14px !important;
        color: #000000 !important;
    }
    .soharon-freeship {
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 12px !important;
        color: #222222 !important;
        text-align: left !important;
    }

    .soharon-checkout-btn {
        width: 340px !important;
        max-width: 100% !important;
        height: 40px !important;
        line-height: 40px !important;
        border-radius: 9px !important;
        background-color: #222222 !important;
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 14px !important;
        color: #ffffff !important;
        margin: 0 auto !important;
        display: block !important;
    }
}

@media (max-width: 767px) {
    .soharon-cart__row .col-price img.aed-symbol,
    .soharon-summary__row img.aed-symbol,
    img.aed-symbol {
        height: 13px !important;
        width: auto !important;
        max-height: 13px !important;
        margin-top: 0 !important;
        vertical-align: middle !important;
        display: inline-block !important;
    }

}
/* FIERRO: center free shipping message */
selector .soharon-freeship { display: block !important; width: 100% !important; text-align: center !important; }


@media (max-width: 767px)
{
h2{
    font-family: 'Jost', sans-serif;
    font-weight: 300;
    font-size: 18px;
    color: #222222;
    margin: 0;
    line-height: 1;
}
}
